      </section>
    </main>
  )
}

async function RelatedProducts() {
  // Keep everything below this call out of the route's App Shell. It renders
  // only on a per-link prefetch (<Link prefetch={true}>) or a navigation.
  await prefetch()
  const relatedProducts = await getRelatedProducts()
  return (
    <ul>
      {relatedProducts.map((product) => (
        <li key={product}>{product}</li>
      ))}
    </ul>
  )
}

